//In hindsight this would have been easier if each property had its own timeline
struct KeyFrame
{
    float time;
    vec2 pos;
    vec2 scale;
};

const vec3 shapeColor = vec3(1.0,0.0,0.0);

const int NUM_KEYFRAMES = 13;

KeyFrame keyFrames[NUM_KEYFRAMES]=KeyFrame[NUM_KEYFRAMES](
    KeyFrame(0.0,vec2(0.0,1.05),vec2(0.07,0.15)),
    KeyFrame(0.2,vec2(0.0,0.2),vec2(0.05,0.2)),
    KeyFrame(0.5,vec2(0.0,-1.0),vec2(0.05,0.2)),    
    KeyFrame(0.55,vec2(0.0,-1.0),vec2(0.18,0.08)),    
    KeyFrame(0.6,vec2(0.0,-0.8),vec2(0.1,0.15)),
    KeyFrame(0.8,vec2(0.0,-0.6),vec2(0.11,0.09)),    
    KeyFrame(1.0,vec2(0.0,-0.5),vec2(0.1,0.1)),    
    KeyFrame(1.1,vec2(0.0,-0.49),vec2(0.1,0.1)),    
    KeyFrame(1.2,vec2(0.0,-0.5),vec2(0.097,0.102)),    
    KeyFrame(1.3,vec2(0.0,-0.55),vec2(0.095,0.105)),    
    KeyFrame(1.5,vec2(0.0,-0.75),vec2(0.09,0.11)),    
    KeyFrame(1.75,vec2(0.0,-1.1),vec2(0.085,0.115)),
    KeyFrame(2.1,vec2(0.0,-1.35),vec2(0.08,0.12))
);

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    uv = uv * 2.0 - 1.0; //-1 to 1
    uv.x *= iResolution.x / iResolution.y;

    float finalTime = keyFrames[NUM_KEYFRAMES-1].time;
    float currentTime = mod(iTime,finalTime);
    int frameIndex = 0;

    //Find keyframes that currentTime falls between
    for(int i = 0; i < NUM_KEYFRAMES-1; i++){
       if (keyFrames[i+1].time > currentTime){
         frameIndex = i;
         break;
       }
    }
    KeyFrame keyA = keyFrames[frameIndex];
    KeyFrame keyB = keyFrames[frameIndex+1];

    //Inverse lerp to get normalized time
    float t = (currentTime - keyA.time) / (keyB.time - keyA.time);

    //Final interpolated position and scale
    vec2 pos = mix(keyA.pos,keyB.pos,t);
    vec2 scale = mix(keyA.scale,keyB.scale,t);

    //Transformed UV
    vec2 p = uv;
    p-= pos;
    p/=scale;

    vec3 col = vec3((uv.y+1.0) / 4.0  + 0.5) * vec3(0.6,0.7,1.0);
    float d = circleSDF(p,1.0);    
    float outlineD = d - 0.08;
    d = smoothstep(-0.01,0.01,d);    
    outlineD = smoothstep(-0.01,0.01,outlineD);
    col = mix(vec3(0),col,outlineD);
    col = mix(shapeColor,col,d);

    float highlightD = circleSDF(p-vec2(-0.3,0.5),0.2);
    highlightD = smoothstep(-0.01,0.01,highlightD);
    col += (1.0 - highlightD);
    // Output to screen
    fragColor = vec4(col,1.0);
}

//2D SDF Functions
//https://iquilezles.org/articles/distfunctions2d/
float circleSDF(vec2 p, float r){
    return length(p)-r;
}
float roundedRectSDF( in vec2 p, in vec2 b, in float r )
{
    vec2 q = abs(p)-b+r;
    return min(max(q.x,q.y),0.0) + length(max(q,0.0)) - r;
}
